def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def bands(values):
        result = []
        i = 0
        while i < len(values):
            if not values[i]:
                i += 1
                continue
            a = i
            while i < len(values) and values[i]:
                i += 1
            result.append((a, i))
        return result

    row_bands = bands([any(v != 0 for v in row) for row in grid])
    if not row_bands:
        return out

    # The first row of each tile band contains the tile borders, making the
    # separated tile columns easy to locate.
    col_bands = bands([grid[row_bands[0][0]][c] != 0 for c in range(w)])
    if not col_bands:
        return out

    tile_h = max(b - a for a, b in row_bands)
    tile_w = max(b - a for a, b in col_bands)
    row_starts = [a for a, _ in row_bands]
    col_starts = [a for a, _ in col_bands]

    interior_counts = {}
    for r in row_starts:
        for c in col_starts:
            for dr in range(1, tile_h - 1):
                for dc in range(1, tile_w - 1):
                    rr, cc = r + dr, c + dc
                    if rr < h and cc < w and grid[rr][cc] != 0:
                        color = grid[rr][cc]
                        interior_counts[color] = interior_counts.get(color, 0) + 1
    if not interior_counts:
        return out
    background = max(interior_counts, key=interior_counts.get)

    # Extend matching interior marks through the blank gutters. Existing
    # tiles are left unchanged.
    for color in interior_counts:
        if color == background:
            continue

        for r in row_starts:
            for dr in range(1, tile_h - 1):
                for dc in range(1, tile_w - 1):
                    cols = []
                    for c in col_starts:
                        rr, cc = r + dr, c + dc
                        if rr < h and cc < w and grid[rr][cc] == color:
                            cols.append(cc)
                    if len(cols) > 1:
                        for cc in range(min(cols), max(cols) + 1):
                            rr = r + dr
                            if out[rr][cc] == 0:
                                out[rr][cc] = color

        for c in col_starts:
            for dc in range(1, tile_w - 1):
                for dr in range(1, tile_h - 1):
                    rows = []
                    for r in row_starts:
                        rr, cc = r + dr, c + dc
                        if rr < h and cc < w and grid[rr][cc] == color:
                            rows.append(rr)
                    if len(rows) > 1:
                        for rr in range(min(rows), max(rows) + 1):
                            cc = c + dc
                            if out[rr][cc] == 0:
                                out[rr][cc] = color

    return out
